import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"WorldVLA: Towards Autoregressive Action World Model","description":"","frontmatter":{"title":"WorldVLA: Towards Autoregressive Action World Model","arxiv":"2506.21539","date":"2025-06-26","authors":"Jun Cen, Chaohui Yu, Hangjie Yuan, Yuming Jiang, Siteng Huang, Jiayan Guo, Xin Li, Yibing Song, Hao Luo, Fan Wang, Deli Zhao, Hao Chen","categories":"cs.RO, cs.AI","topics":"动作世界模型, 自回归 VLA, 注意力掩码","outline":[2,2]},"headers":[],"relativePath":"papers/2506.21539.md","filePath":"papers/2506.21539.md","lastUpdated":null}'),e={name:"papers/2506.21539.md"};function l(r,s,m,i,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="worldvla-towards-autoregressive-action-world-model" tabindex="-1">WorldVLA: Towards Autoregressive Action World Model <a class="header-anchor" href="#worldvla-towards-autoregressive-action-world-model" aria-label="Permalink to &quot;WorldVLA: Towards Autoregressive Action World Model&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2506.21539" target="_blank" rel="noreferrer">2506.21539</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-06-26</td></tr><tr><td><strong>作者</strong></td><td>Jun Cen, Chaohui Yu, Hangjie Yuan, Yuming Jiang, Siteng Huang, Jiayan Guo, Xin Li, Yibing Song, Hao Luo, Fan Wang, Deli Zhao, Hao Chen</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>把图像、文本、动作压成同一套离散 token 交给一个自回归 LLM，让世界模型与动作模型在同一组权重里互相增强；再用一个动作注意力掩码切断 action chunk 内部的误差传播。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/video-for-embodied-ai">视频生成赋能具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>VLA 模型把动作当作输出，从不把动作当作输入去理解；世界模型把动作当作输入去预测未来画面，却输出不了动作。这两件事在工程上被拆成两套模型、两套权重、两条数据管线，而它们要学的其实是同一个东西：这个环境在给定动作下会怎么变。本文要问的是，能不能让同一组参数同时承担这两个角色，并且互相受益。</p><p>这个问题重要，是因为动作监督天然稀疏。一条演示轨迹里，观测是几十万维的像素，动作只有 7 个数。纯行为克隆的梯度信号密度低，模型很容易退化成&quot;看到这个场景就播放这段肌肉记忆&quot;。世界模型提供的是像素空间的稠密监督，而且这个监督被动作显式条件化，所以它逼着模型去解释&quot;这个动作导致了画面里的哪一处变化&quot;。如果这条路走通，视频数据就能作为动作学习的免费监督源。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>作者在表 1 里把相关工作按输入输出画成一个 2×2：动作模型（OpenVLA、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>）吃文本+视频出动作；视频预测模型（MAGVIT、SVD）吃文本+视频出视频；世界模型（iVideoGPT、DWS）吃文本+视频+动作出视频；只有 UVA 和本文落在&quot;动作世界模型&quot;这一格。</p><p>具体的不足是这样的。GR-1/GR-2 那条线用<strong>视频预测</strong>给动作模型做预训练，但视频预测不以动作为条件，同一张起始帧对应多个合法未来，训练信号里混进了不可约的歧义。iVideoGPT 这类世界模型解决了歧义问题，却把动作只当条件、不当输出，于是必须外挂一个 inverse dynamics 或者独立策略才能落地。UVA 用两个独立的 diffusion head 分别生成图像和动作，共享的只是主干特征，两条生成路径在 token 层面并不互相看见。本文选的是另一条路：把图像、文本、动作全部离散化到同一个词表里，让统一的 next-token 目标去承载所有关系。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>出发点应该是 Chameleon 这类统一理解-生成模型的既有事实：图像可以被 VQ-GAN 压成离散 token，和文本共用一个词表、一个 transformer、一个交叉熵损失。既然图像能这么做，动作为什么不能——OpenVLA 已经证明把每个动作维度离散成 256 个 bin 是可行的，7 个 token 就是一步动作。三种模态都变成 token 之后，&quot;世界模型&quot;和&quot;动作模型&quot;就只是同一个序列模型上两种不同的输入输出布局，混在一个 batch 里训练是自然的。</p><p>第二步的观察来自失败。作者试图让这个自回归模型一次吐出一串动作（action chunk），发现成功率不升反降。这个现象本身是有解释力的：MLLM 的预训练语料里有海量图文，没有动作，所以动作这个模态的泛化能力是三者中最弱的一环。而因果注意力恰恰让第 k 个动作去看第 1..k−1 个动作——把最不可靠的模态放在了条件位置上。顺着这个诊断，修法就很直接：不让动作看动作，只让动作看图像和文本。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>两句话。第一，世界模型和动作模型共享参数时，&quot;预测动作导致的画面变化&quot;这个任务会强迫模型把动作解释成物理量而不是符号，反过来让动作生成更靠谱；同时&quot;生成动作&quot;要求的视觉理解又提升了画面生成质量。第二，自回归模型在动作这个弱泛化模态上做链式条件是自伤——把 chunk 内的因果链剪断、让每个动作只依赖视觉，误差就无法沿着 chunk 累积。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以 LIBERO-Goal 的一次抓取为例：</p><ol><li><strong>tokenize</strong>：两帧 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">256</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">256</span></span></span></span> 历史观测经 VQ-GAN（压缩率 16、码本 8192）各变成 256 个 token（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">512</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">512</span></span></span></span> 时是 1024 个）；指令被包装成 &quot;What action should the robot take to + 任务指令 + ?&quot; 后走 BPE 分词；动作的 3 个相对位移、3 个相对角度、1 个绝对夹爪状态各离散成 256 个 bin，共 7 个 token。词表大小 65,536，其中 8192 个给图像、256 个给动作。</li><li><strong>动作数据布局</strong>：<code>[BOS]{text}([BOI]{image}...[EOI])×M [EOS] ([BOA]{action}[EOA])×K [EOS]</code>，只在动作 token 上算损失。默认 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span>（LIBERO-Long 用 10）。</li><li><strong>世界模型数据布局</strong>：<code>[BOS]{text}([BOI]{image}[EOI][BOA]{action}[EOA][EOS] [BOI]{image}[EOI][EOS])×N</code>，只在生成的图像 token 上算损失，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>。注意这条数据<strong>不需要任务指令</strong>，因为动作已经完全决定了下一状态。</li><li><strong>注意力掩码</strong>：世界模型部分保持标准因果掩码；动作部分改成&quot;当前动作只能看文本和图像，看不到之前的动作&quot;，于是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span></span></span></span> 个动作实际上是并行解码的。</li><li><strong>推理</strong>：给两帧观测和指令，一次吐出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span></span></span></span> 个动作送去执行，不生成图像。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>总损失是两路交叉熵的加权和：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight">c</span><span class="mord mathnormal mtight">t</span><span class="mord mathnormal mtight">i</span><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0269em;">w</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">or</span><span class="mord mathnormal mtight" style="margin-right:0.0197em;">l</span><span class="mord mathnormal mtight">d</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord">.</span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> 取 0.04。作者给的理由是 token 数量悬殊——一帧 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">512</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">512</span></span></span></span> 图像是 1024 个 token，一步动作只有 7 个，不加权的话梯度会被图像重建完全主导。</p><p>真正有意思的是掩码改动的概率含义。标准因果分解是</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.1304em;vertical-align:-1.3021em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8479em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∏</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.3021em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mrel mtight">&lt;</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1774em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mclose">)</span><span class="mpunct">,</span></span></span></span></span></p><p>而本文的掩码把它换成了边缘分布的乘积</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.1304em;vertical-align:-1.3021em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8479em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∏</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.3021em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">o</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0197em;">l</span><span class="mclose">)</span><span class="mord">.</span></span></span></span></span></p><p>第二式只有在&quot;给定观测和指令后，chunk 内各步动作条件独立&quot;时才等于第一式，而这个条件显然不成立——连续动作之间高度相关。所以这不是一个更好的分解，而是一次<strong>用表达力换稳定性</strong>的交易：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span></span></span></span> 丢掉了 chunk 内的相关结构，但也切断了误差沿 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 传播的路径。设单步条件预测的错误率为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span></span></span></span>，因果分解下一次错误会污染后续所有条件，chunk 正确率大致按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">p</span><span class="mclose">)</span></span></span></span> 的复合方式衰减；掩码版本下每步错误彼此独立，不放大。表 3 的数据支持这个交易：naive 因果 chunking 的平均成功率是 54.0%，改掩码后升到 76.6%。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>世界模型是否帮到动作模型？</strong> 表 3 用同一骨干做单变量对照：只有动作数据 62.8%，加入世界模型数据 67.2%（+4.4 点）；在都开 chunking+新掩码的条件下是 76.6% → 78.1%（+1.5 点）。表 6 换一种用法——先用世界模型数据做预训练再做动作微调——62.8% → 66.8%，与混合训练几乎等价。作者另做了一组对照，把世界模型换成不以动作为条件的<strong>视频预测</strong>模型：世界模型在全部任务上都有增益，视频预测只在两个任务上有益、一个任务上有害。这是全文对&quot;动作条件化&quot;最直接的辩护。</p><p><strong>动作模型是否帮到世界模型？</strong> 表 4 只有部分支持。50 帧长视频上 FVD 从 718.6 降到 674.1（−6.2%），PSNR 23.98→24.30；但 10 帧短视频上 FVD 反而从 250.0 升到 255.1，SSIM 90.73→90.40。摘要与引言称&quot;FVD 降低 10%&quot;，两个设定下都对不上这个数字，需要按表读。</p><p><strong>benchmark 定位。</strong> 表 2 中 WorldVLA（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">512</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">512</span></span></span></span>）平均 81.8%，高于同为离散动作模型且经过预训练的 OpenVLA（76.5%），但明显低于 OpenVLA-OFT（95.4%）与 UVA（93.0%，仅 Long）。分辨率从 256 提到 512 带来 79.1% → 81.8% 的提升，作者归因于 Chameleon 骨干本身就在 512 上预训练。另外表 2 用了全部数据，消融表用的是 90% 划分，两者不可直接对齐。</p><p><strong>历史帧与吞吐。</strong> 表 5 显示 1/2/4 帧输入在开 chunking 时是 74.0/84.4/84.7%，两帧后饱和；FPS 则从 3.67 单调降到 2.78。默认取两帧是性价比选择。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版。</strong> WorldVLA 用一个离散自回归 LLM 同时承担 VLA 与世界模型，三种模态共享词表与损失。世界模型数据给动作学习提供了以动作为条件的稠密像素监督，比不带动作条件的视频预测更可靠。自回归逐个生成 action chunk 会因动作模态泛化弱而累积误差，平均成功率从 62.8% 掉到 54.0%。把 chunk 内的动作-动作注意力剪掉后回升到 76.6%，再叠加世界模型数据到 78.1%。代价是丢掉了 chunk 内的时序相关结构，且整体成功率仍落后于连续动作头的 SOTA。</p><p><strong>三句话版。</strong> 动作、图像、文本共用一个自回归 transformer，世界模型与动作模型互相提升。chunk 内动作互看会放大误差，切断它是关键修复。离散 tokenization 带来的信息损失使其仍不敌连续动作头。</p><p><strong>一句话版。</strong> 统一 token 空间让世界建模成为动作学习的稠密监督，但动作这一模态的自回归条件必须被切断。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的是&quot;世界模型学到的是环境物理&quot;这一假设。全文对它的唯一定量支撑是像素级重建指标（FVD/PSNR/SSIM/LPIPS）加上下游成功率的提升，而这两者都无法区分&quot;模型理解了接触与摩擦&quot;与&quot;模型学会了在给定 7 个动作 token 时把机械臂像素平移到对应位置&quot;。后者是一个纯运动学的渲染技巧，在 LIBERO 这种固定相机、固定臂型、背景静止的环境里几乎足以最小化重建损失。</p><p>如果这个假设不成立，第 7 节的所有增益就应该被重新解释为&quot;多任务正则化&quot;：模型被迫维持一个能重建观测的视觉表征，从而抑制了纯 BC 的过拟合。论文提供的最强反证据是视频预测对照实验——不带动作条件时增益消失甚至转负，说明动作确实被用上了。但&quot;动作被用来对齐像素&quot;和&quot;动作被理解为物理量&quot;仍未被区分开。缺的是把动作扰动后看预测画面是否发生<strong>物理上正确</strong>的改变（例如推力方向反了，物体应当往另一侧移动），而不只是机械臂位姿变了。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做，不需要复现整个系统：</p><ul><li>取一个现成的小型离散 VLA（或直接用作者开源的 WorldVLA 权重），在 LIBERO-Spatial 上冻结骨干，只改注意力掩码，做 A/B：因果 chunk 掩码 vs 动作互不可见掩码，chunk 长度扫 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">3</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">5</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">10</span><span class="mclose">}</span></span></span></span>，每任务 50 rollout。</li><li>测量：成功率随 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span></span></span></span> 的曲线，以及<strong>同一 chunk 内第 1 步与第 K 步的单步动作 L1 误差</strong>（在验证集轨迹上离线算，不需要 rollout）。</li><li>判据：若因果版本的第 K 步误差随 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span></span></span></span> 单调上升而掩码版本平坦，则&quot;误差沿 chunk 传播&quot;的机制成立；若两者都平坦而成功率仍差很多，说明增益另有来源（例如并行解码改变了动作分布的多样性），本文的解释被削弱。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>替代解释：新掩码的收益可能主要来自<strong>推理时的解码分布改变</strong>，而非训练时的误差传播。在因果掩码下，逐步采样会让早期的一次高熵采样把后续动作整体带偏（典型的曝光偏差）；而并行解码等价于对每一步取各自的边缘众数，本质上是一种更保守、方差更小的解码。要检验这一点，只需在<strong>同一个因果训练的模型</strong>上改用 teacher-forcing 式的贪心并行推理（即把前置动作位置填入模型自己的边缘预测而非采样值），如果成功率大幅回升，那么真正起作用的是解码方差而不是训练时的注意力结构，本文的掩码就可以被一个纯推理端的修改替代。</p><p>第二个攻击面是环境本身。LIBERO 是固定相机、无外部扰动的确定性仿真，chunk 内&quot;动作条件独立&quot;这个错误假设的代价被压到最低。在真实机械臂上，接触事件会让第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 步的正确动作强烈依赖于第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7778em;vertical-align:-0.0833em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 步的实际结果，此时丢掉 chunk 内相关性应当出现可预测的失败——例如插入、拧螺丝这类需要力反馈微调的任务。论文没有任何真机实验，这个失败模式完全未被检验。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限</strong>：本文实际上证明了一件更一般的事——在多模态自回归模型里，不同模态的泛化能力差异巨大，而因果注意力默认所有 token 一律平等地作为条件。弱模态一旦进入条件位置就成为误差源。本文的解法是硬编码一张掩码，只对&quot;动作&quot;这一类 token 生效。</p><p><strong>(b) 可借鉴的相邻工具</strong>：推测解码（speculative decoding）与 mixture-of-denoisers 训练里已经有成熟的&quot;按 token 可靠性动态调整依赖结构&quot;的机制；conformal prediction 则提供了在推理时对每个 token 给出可靠性区间的手段。</p><p><strong>(c) 第一个实验</strong>：把掩码从静态改成<strong>可学习的、以预测熵为门控的</strong>依赖结构——训练时对每个动作 token 估计其自身的预测不确定度，只允许下游 token 注意到不确定度低于阈值的前置动作。在 LIBERO 上先验证它能自动恢复出本文的全掩码（说明门控起作用），再在含接触事件的任务（如 LIBERO-Long 的长程序列）上检验它是否比全掩码更好——因为那里 chunk 内的相关性是真实且有用的，全掩码应当过于保守。这把&quot;要不要看前一步动作&quot;从一个二元设计选择变成一个由不确定度决定的连续量。</p>',48)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
